import{_ as l,o as e,c as t,aw as o}from"./chunks/framework.DLufY-ao.js";const g=JSON.parse('{"title":"Собрания","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/agile/meetings.md","filePath":"wiki/dev-commit/theory/agile/agile/meetings.md"}'),a={name:"wiki/dev-commit/theory/agile/agile/meetings.md"};function r(n,i,s,c,u,m){return e(),t("div",null,[...i[0]||(i[0]=[o('<h1 id="собрания" tabindex="-1">Собрания <a class="header-anchor" href="#собрания" aria-label="Permalink to &quot;Собрания&quot;">​</a></h1><h2 id="planning-poker-scrum-poker" tabindex="-1">Planning Poker / Scrum Poker <a class="header-anchor" href="#planning-poker-scrum-poker" aria-label="Permalink to &quot;Planning Poker / Scrum Poker&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определения</p><ul><li><strong>Planning Poker / Scrum Poker</strong> - разбиение Сторис на задачи и оценка сложности задач в Story Points</li><li><strong>Story Points</strong> - оценивание с точки зрения сложности. Определяются эталонные задачи (кто за сколько врмени выполнял задачу). Отталкиваясь от эталонный оцениваются все остальные Сторис</li><li>У всех на собрании есть карты на которых выставолены числа, соответствующие кол-ву Story Points. Для более честной оценки все взакрытую при объявлении задачи выбирают свое количество Story Points и после показывают что поставили</li><li>Набор задач в спринт</li></ul></div><h2 id="retrospective" tabindex="-1">Retrospective <a class="header-anchor" href="#retrospective" aria-label="Permalink to &quot;Retrospective&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Ретроспектива</p><ul><li><strong>Ретроспектива</strong> - любое время, когда команда размышляет о прошлом, чтобы улучшить будущее. Помимо рабочих вопросов в технических и нетехнических командах, ретроспективы можно устраивать практически по любым темам</li></ul></div><ul><li>Проходит после review</li><li>Каждый в команде по очереди высказывается и предлагает варианты улучения процесса</li><li>К концу ретроспективы список элементов на улучшение, который к концу следующего спринта смотрится и проверяется что улучшили, а что нет</li><li>Оценивается эффуктивность команды. Берутся стори которые были закрыты и суммируются их Story Points. Если команда закрыра 30 Story Points, значит в следующем спринте можно запланировать 30 Story Points</li></ul><p><strong>Собрание на которым команда отвечает на вопросы</strong></p><ul><li>&quot;Что было сделано хорошо в Спринте&quot;</li><li>&quot;Что мы делали плохо в спринте&quot;</li><li>&quot;Что нужно сделать чтобы в следующем спринте работать лучше&quot;</li></ul><h2 id="daily-scrum-meeting-daily-stand-up" tabindex="-1">Daily Scrum Meeting / Daily Stand-Up <a class="header-anchor" href="#daily-scrum-meeting-daily-stand-up" aria-label="Permalink to &quot;Daily Scrum Meeting / Daily Stand-Up&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Daily Scrum Meeting</p><ul><li><strong>Daily Scrum Meeting/Stand-Up</strong> - 15 минут ежедневно проводятся встречи проектной команды, где контролируется ход работ. Каждый участник команды рассказывает про свой текущий статус: - Что делал вчера? - Что буду делать сегодня? - Какие проблемы есть?</li></ul></div><h2 id="backlog-refinement-grooming" tabindex="-1">Backlog refinement (Grooming) <a class="header-anchor" href="#backlog-refinement-grooming" aria-label="Permalink to &quot;Backlog refinement (Grooming)&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">acklog refinement</p><ul><li><strong>Backlog refinement (grooming)</strong> - встречи с участием владельца продукта и скрам-команды, в ходе которой содержимое BACKLOG актуализируется для следующего спринта</li><li>Практика backlog refinement помогает контролировать постоянно растущий BACKLOG</li></ul></div><ul><li>Может занимать до 10% времени от спринта</li><li>Требования от заказчика превращаются в задачи и оцениваются (декомпозиция задач)</li><li>Цель грумминга - понять какие задачи мы закрываем, какие задачи переносим на следующий спринт</li></ul><h2 id="kick-off" tabindex="-1">Kick-Off <a class="header-anchor" href="#kick-off" aria-label="Permalink to &quot;Kick-Off&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Kick-Off</p><ul><li><strong>Kick-Off</strong> (вводная встреча) - это первая встреча с участниками проекта и возможно приглашение заказчиков проекта. Эта встреча должна определить основные элементы проекта и другие мероприятия по планированию</li></ul></div><ul><li>Требования от заказчика передаются команде (обсуждение всей командой описанного и отрисованного функционала, чтобы все понимали в чём смысл функционала)</li></ul><h2 id="сессия-временнои-оценки-задач" tabindex="-1">Сессия временной оценки задач <a class="header-anchor" href="#сессия-временнои-оценки-задач" aria-label="Permalink to &quot;Сессия временной оценки задач&quot;">​</a></h2><ul><li>Сессия временной оценки задач. Назначаются ответственные за задачи. По итогу есть список задач который помещается в список TODO - задач на разработку. Задачи оцененные, приориетизированные, есть назначенные разработчики. После этого спринт считается запущенным</li></ul>',18)])])}const k=l(a,[["render",r]]);export{g as __pageData,k as default};
